public class Escape {
    static class Point { final int x, y;
                         Point(int x, int y) { this.x=x; this.y=y; }
                         int sum() { return x + y; } }
    static long total;
    public static void main(String[] a) {
        int n = Integer.parseInt(a[0]);
        long t0 = System.nanoTime(), s = 0;
        for (int i = 0; i < n; i++) {
            Point p = new Point(i, i + 1);
            s += p.sum();
        }
        total = s;                      // 결과를 밖으로 내보내 계산이 안 사라지게 한다
        System.out.printf("%,d회  %,d ms  (s=%d)%n", n, (System.nanoTime()-t0)/1_000_000, total);
    }
}

# --- 1) 기본 ---

$ java -Xmx256m -Xlog:gc -cp out Escape 500000000
[0.004s][info][gc] Using G1
500,000,000회  311 ms  (s=250000000000000000)

$ java -Xmx256m -Xlog:gc -cp out Escape 500000000 | grep -c 'Pause Young'
0                                  <- GC 가 한 번도 안 일어났다

# --- 2) 탈출 분석을 끈다 ---

$ java -Xmx256m -XX:-DoEscapeAnalysis -Xlog:gc -cp out Escape 500000000
[0.807s][info][gc] GC(150) Pause Young (Normal) (G1 Evacuation Pause) 77M->1M(130M) 0.213ms
500,000,000회  793 ms  (s=250000000000000000)

$ ... | grep -c 'Pause Young'
151                                <- 5억 개가 실제로 만들어지고 치워졌다

# 두 실행의 s 값이 같다. 계산은 똑같이 했고 객체만 안 만들었다.
